: 'return-invisible';\t\n}","// Handles pasting sigs from EVE\ntripwire.pasteSignatures = function() {\n    var processing = false;\n\n    var rowParse = function(row) {\n        var scanner = {};\n        var columns = row.split(\"\t\"); // Split by tab\n        var validScanGroups = [\n            // English (en-us)\n            \"Cosmic Signature\",\n            \"Cosmic Anomaly\",\n\n            // French (fr)\n            \"Signature cosmique\",\n            \"Anomalie cosmique\",\n\n            // German (de)\n            \"Kosmische Anomalie\",\n            \"Kosmische Signatur\",\n\n            // Japanese (ja)\n            \"宇宙の特異点\",\n            \"宇宙のシグネチャ\",\n\n            // Korean (ko)\n            \"코즈믹 시그니처\",\n            \"코즈믹 어노말리\",\n\n            // Russian (ru)\n            \"Скрытый сигнал\",\n            \"Космическая аномалия\",\n        ];\n\n        var validTypes = {\n            // English (en-us)\n            \"Combat Site\": \"Combat\",\n            \"Data Site\": \"Data\",\n            \"Gas Site\": \"Gas\",\n            \"Ore Site\": \"Ore\",\n            \"Relic Site\": \"Relic\",\n            \"Wormhole\": \"Wormhole\",\n            \"Homefront Operations\": \"Combat\",\n\n            // French (fr)\n            \"Site de combat\": \"Combat\",\n            \"Site de données\": \"Data\",\n            \"Site de collecte de gaz\": \"Gas\",\n            \"Site de minerai\": \"Ore\",\n            \"Site de reliques\": \"Relic\",\n            \"Trou de ver\": \"Wormhole\",\n\n            // German (de)\n            \"Kampfgebiet\": \"Combat\",\n            \"Datengebiet\": \"Data\",\n            \"Gasgebiet\": \"Gas\",\n            \"Mineraliengebiet\": \"Ore\",\n            \"Reliktgebiet\": \"Relic\",\n            \"Wurmloch\": \"Wormhole\",\n\n            // Japanese (ja)\n            \"戦闘サイト\": \"Combat\",\n            \"データサイト\": \"Data\",\n            \"ガスサイト\": \"Gas\",\n            \"鉱石サイト\": \"Ore\",\n            \"遺物サイト\": \"Relic\",\n            \"ワームホール\": \"Wormhole\",\n\n            // Korean (ko)\n            \"전투 사이트\": \"Combat\",\n            \"데이터 사이트\": \"Data\",\n            \"가스 사이트\": \"Gas\",\n            \"채광 사이트\": \"Ore\",\n            \"유물 사이트\": \"Relic\",\n            \"웜홀\": \"Wormhole\",\n\n            // Russian (ru)\n            \"Боевой район\": \"Combat\",\n            \"Информационный район\": \"Data\",\n            \"Газовый район\": \"Gas\",\n            \"Астероидный район\": \"Ore\",\n            \"Археологический район\": \"Relic\",\n            \"Червоточина\": \"Wormhole\",\n        };\n\n        for (var x in columns) {\n            if (columns[x].match(/^([A-Z]{3}[-]\\d{3})$/)) {\n                scanner.id = columns[x].split(\"-\");\n                continue;\n            }\n\n            if (columns[x].match(/(\\d([.|,]\\d)?[ ]?(%))/) || columns[x].match(/(\\d[.|,]?\\d+\\s?(UA|AU|AE|km|m|а.е.|км|м))/i)) { // Exclude scan % || AU\n                continue;\n            }\n\n            if ($.inArray(columns[x], validScanGroups) != -1) {\n                scanner.scanGroup = columns[x];\n                continue;\n            }\n\n            if (validTypes[columns[x]]) {\n                scanner.type = validTypes[columns[x]];\n                continue;\n            }\n\n            if (columns[x] != \"\") {\n                scanner.name = columns[x].trim();\n            }\n        }\n\n        if (!scanner.id || scanner.id.length !== 2) {\n            return false;\n        }\n\n        return scanner;\n    }\n\n    this.pasteSignatures.parsePaste = function(paste) {\n        var paste = paste.split(\"\\n\");\n        var payload = {\"signatures\": {\"add\": [], \"update\": []}, \"systemID\": viewingSystemID};\n        var undo = [];\n        processing = true;\n\n        for (var i in paste) {\n            var scanner = rowParse(paste[i]);\n\n            if (scanner.id) {\n                var signature = $.map(tripwire.client.signatures, function(signa